22	  // cloned from ImmutableCollection
23	  static int expandedCapacity(int oldCapacity, int minCapacity) {
24	    if (minCapacity < 0) {
25	      throw new IllegalArgumentException("cannot store more than Integer.MAX_VALUE elements");
26	    } else if (minCapacity <= oldCapacity) {
27	      return oldCapacity;
28	    }
29	    // careful of overflow!
30	    int newCapacity = oldCapacity + (oldCapacity >> 1) + 1;
31	    if (newCapacity < minCapacity) {
32	      newCapacity = Integer.highestOneBit(minCapacity - 1) << 1;
33	    }
34	    if (newCapacity < 0) {
35	      newCapacity = Integer.MAX_VALUE;
36	      // guaranteed to be >= newCapacity
37	    }
38	    return newCapacity;
39	  }
